68	    /**
69	     * Verifica che ogni valore dinamico fornito nel JSON venga effettivamente risolto e
70	     * stampato nel documento. Un path errato in una fieldDescription tornerebbe null e il
71	     * valore non comparirebbe nel testo: in quel caso il test fallisce elencando i valori
72	     * non risolti.
73	     */
74	    @Test
75	    public void nonRestanoValoriDinamiciIrrisolti() throws Exception {
76	        ObjectMapper mapper = new ObjectMapper();
77	        ObjectNode data = buildData(mapper);
78	
79	        JasperPrint jasperPrint = fillReport(mapper, data);
80	        String testoStampato = estraiTestoStampato(jasperPrint);
81	
82	        List<String> valoriMancanti = new ArrayList<>();
83	        for (String valoreAtteso : raccogliValoriDinamici(data)) {
84	            if (!testoStampato.contains(valoreAtteso)) {
85	                valoriMancanti.add(valoreAtteso);
86	            }
87	        }
88	
89	        assertTrue("Valori dinamici non risolti nel documento generato: " + valoriMancanti,
90	                valoriMancanti.isEmpty());
91	    }
92	
93	    /**
94	     * Variante con tutti gli importi a zero. Serve a ispezionare visivamente come vengono
95	     * resi i valori monetari nulli (es. "€ 0,00") nelle premesse e nell'Art. 2.
96	     */
97	    @Test
98	    public void generaPdfImportiAZero() throws Exception {
99	        ObjectMapper mapper = new ObjectMapper();
100	        ObjectNode data = buildData(mapper);
101	
102	        ObjectNode determina2025 = (ObjectNode) data.get("determina2025");
103	        determina2025.put("importoAssegnato2025", IMPORTO_ZERO);
104	
105	        ObjectNode provvedimento2026 = (ObjectNode) data.get("provvedimento2026");
