114	    /**
115	     * Variante con stringhe molto ampie su denominazione, titoli, indirizzo e capitolo di
116	     * spesa. Serve a ispezionare visivamente l'assenza di sovrapposizioni di testo e il
117	     * comportamento del cambio pagina. L'assert verifica che il contenuto più esteso produca
118	     * più pagine della baseline: se il testo si sovrapponesse o venisse troncato invece di
119	     * espandere i band, le pagine non aumenterebbero.
120	     */
121	    @Test
122	    public void generaPdfTestiAmpiVerificaImpaginazione() throws Exception {
123	        ObjectMapper mapper = new ObjectMapper();
124	
125	        int pagineBaseline = fillReport(mapper, buildData(mapper)).getPages().size();
