165	        ObjectNode progetto = (ObjectNode) data.get("progetto");
166	        progetto.put("titoloProgetto2026", testoMoltoLungo(
167	                "Stagione Teatrale, Musicale e di Danza Contemporanea della Regione Puglia", 5));
168	        progetto.put("titoloProgrammazioneTriennale", testoMoltoLungo(
169	                "Programma Artistico Triennale Integrato per la Valorizzazione del Patrimonio Culturale Immateriale", 4));
170	
171	        ObjectNode provvedimento2026 = (ObjectNode) data.get("provvedimento2026");
172	        provvedimento2026.put("denominazioneCapitoloSpesa2026", testoMoltoLungo(
173	                "Spese per il sostegno alle attività culturali e di spettacolo dal vivo di interesse regionale", 4));
174	    }
