176	    private void svuotaCampi(ObjectNode data) {
177	        ObjectNode determina2025 = (ObjectNode) data.get("determina2025");
178	        determina2025.put("importoAssegnato2025", "");
179	        determina2025.put("numeroCapitoloRegionale2025", "");
180	        determina2025.put("dataSottoscrizioneDisciplinare2025", "");
181	
182	        ObjectNode provvedimento2026 = (ObjectNode) data.get("provvedimento2026");
183	        provvedimento2026.put("importoAssegnato2026", "");
184	        provvedimento2026.put("numeroProtocolloDomandaProgetto2026", "");
185	        provvedimento2026.put("denominazioneCapitoloSpesa2026", "");
186	
187	        ObjectNode attoAmmissione2026 = (ObjectNode) data.get("attoAmmissione2026");
188	        attoAmmissione2026.put("importoAssegnato", "");
189	        attoAmmissione2026.put("numeroAttoDirigenzialeAmmissione2026", "");
190	        attoAmmissione2026.put("dataAttoDirigenzialeAmmissione2026", "");
191	    }
