193	    private String testoMoltoLungo(String frase, int ripetizioni) {
194	        StringBuilder testo = new StringBuilder();
195	        for (int i = 0; i < ripetizioni; i++) {
196	            if (i > 0) {
197	                testo.append(' ');
198	            }
199	            testo.append(frase);
200	        }
201	        return testo.toString();
202	    }
203	
204	    private void generaPdf(ObjectMapper mapper, ObjectNode data, String outputFileName) throws Exception {
205	        JasperPrint jasperPrint = fillReport(mapper, data);
206	
207	        Path outputPath = writePdf(jasperPrint, outputFileName);
208	
209	        assertTrue("Il PDF generato non esiste: " + outputPath, Files.exists(outputPath));
210	        assertTrue("Il PDF generato è vuoto: " + outputPath, Files.size(outputPath) > 0);
211	    }
212	
213	    private JasperPrint fillReport(ObjectMapper mapper, ObjectNode data) throws Exception {
214	        JasperReport mainReport = compile(MAIN_REPORT);
215	
216	        byte[] jsonBytes = mapper.writeValueAsBytes(data);
217	        JsonDataSource dataSource = new JsonDataSource(new ByteArrayInputStream(jsonBytes));
218	
219	        Map<String, Object> parameters = new HashMap<>();
220	        parameters.put(PARAM_NOME_COGNOME_UTENTE, NOME_COGNOME_UTENTE);
221	
222	        return JasperFillManager.fillReport(mainReport, parameters, dataSource);
223	    }
224	
225	    private String estraiTestoStampato(JasperPrint jasperPrint) {
226	        StringBuilder testo = new StringBuilder();
227	        for (JRPrintPage page : jasperPrint.getPages()) {
228	            accumulaTesto(page.getElements(), testo);
229	        }
230	        return testo.toString();
231	    }
232	
233	    private void accumulaTesto(Collection<JRPrintElement> elementi, StringBuilder testo) {
234	        for (JRPrintElement elemento : elementi) {
235	            if (elemento instanceof JRPrintText) {
236	                testo.append(((JRPrintText) elemento).getFullText()).append('\n');
237	            } else if (elemento instanceof JRPrintFrame) {
238	                accumulaTesto(((JRPrintFrame) elemento).getElements(), testo);
239	            }
240	        }
241	    }
242	
243	    private List<String> raccogliValoriDinamici(JsonNode nodo) {
244	        List<String> valori = new ArrayList<>();
245	        accumulaValoriDinamici(nodo, valori);
246	        return valori;
247	    }
248	
249	    private void accumulaValoriDinamici(JsonNode nodo, List<String> valori) {
250	        if (nodo.isObject()) {
251	            for (JsonNode figlio : nodo) {
252	                accumulaValoriDinamici(figlio, valori);
253	            }
254	        } else if (nodo.isValueNode()) {
255	            valori.add(nodo.asText());
256	        }
257	    }
258	
259	    private JasperReport compile(String resourcePath) throws Exception {
260	        try (InputStream stream = getClass().getResourceAsStream(resourcePath)) {
261	            if (stream == null) {
262	                throw new IllegalStateException("Risorsa jrxml non trovata nel classpath: " + resourcePath);
263	            }
264	            return JasperCompileManager.compileReport(stream);
265	        }
266	    }
267	
268	    private Path writePdf(JasperPrint jasperPrint, String outputFileName) throws Exception {
269	        Path outputDir = Paths.get(OUTPUT_DIR);
270	        Files.createDirectories(outputDir);
271	        Path outputPath = outputDir.resolve(outputFileName);
272	
273	        try (OutputStream outputStream = Files.newOutputStream(outputPath)) {
274	            JRPdfExporter exporter = new JRPdfExporter();
275	            exporter.setExporterInput(new SimpleExporterInput(jasperPrint));
276	            exporter.setExporterOutput(new SimpleOutputStreamExporterOutput(outputStream));
277	            exporter.exportReport();
278	        }
279	        return outputPath;
280	    }
281	
